"""Generate the measured-results document directly from evaluation JSON."""

import json
from pathlib import Path


def main():
    summary = json.loads(Path("results/metrics.json").read_text())
    lines = [
        "# Measured results",
        "",
        "Test: April 1 to December 31, 2012. 275 dates per horizon. All values",
        "below come from `results/metrics.json`, generated by `bike_backtest.run eval`.",
        "Regenerate this document with `python -m bike_backtest.report`.",
        "",
        "| Horizon | Model | MAE | RMSE | WAPE (%) |",
        "| :--- | :--- | ---: | ---: | ---: |",
    ]
    labels = {
        "persistence": "Persistence",
        "weekly_baseline": "Seasonal naive",
        "poisson": "Poisson",
        "tree": "LightGBM",
    }
    for horizon in summary["horizons"]:
        h = horizon["horizon_days"]
        for name, values in horizon["metrics"].items():
            lines.append(
                f"| {h} day | {labels[name]} | {values['mae']:.2f} | "
                f"{values['rmse']:.2f} | {values['wape_percent']:.2f} |"
            )
    lines += ["", "## Quantile intervals and paired error comparison", ""]
    for horizon in summary["horizons"]:
        h = horizon["horizon_days"]
        interval = horizon["interval"]
        block = horizon["paired_block_bootstrap"]
        lines += [
            f"### {h}-day horizon",
            "",
            f"Selected LightGBM configuration: `{horizon['selected_model']}`.",
            f"MAE reduction versus seasonal naive: {horizon['mae_reduction_vs_weekly_percent']:.2f}%.",
            f"Nominal 80% interval coverage: {100 * interval['observed_coverage']:.2f}%.",
            f"Mean interval width: {interval['mean_width']:.2f} rentals/day.",
            f"Pinball loss (0.1 / 0.9): {interval['pinball_0.1']:.2f} / {interval['pinball_0.9']:.2f}.",
            f"Paired mean MAE gain: {block['mean_mae_gain']:.2f} rentals/day; descriptive",
            f"95% block-bootstrap interval [{block['lower_95']:.2f}, {block['upper_95']:.2f}].",
            "",
        ]
    lines += [
        "## Interpretation",
        "",
        "At one day, LightGBM beats seasonal naive by MAE, but persistence is better.",
        "At seven days, LightGBM is worse than seasonal naive. Poisson is not a",
        "winning replacement for the simple baselines in this experiment either.",
        "Both bootstrap intervals include zero. No reliable superiority claim is made.",
        "The raw quantile bands under-cover badly and need further work before use.",
        "No hourly result is reported: only daily data is used.",
        "",
    ]
    Path("RESULTS.md").write_text("\n".join(lines))


if __name__ == "__main__":
    main()
